    cmd.select(ALIAS_2_NUM, ALIAS_2, ALIAS_2_NEW);
    cmd.select(AMOUNT, t.C_NUMBER);
    // date as constant
    cmd.select(db.getValueExpr(DateUtils.getDateNow(), DataType.DATE).as(t.C_DATE));
    DBColumnExpr[] expr = cmd.getSelectExprList();
    // Hint: ALIAS_2_NEU is not a separate column
