        reader.open(cmd);
        while (reader.moveNext()) {
            byte[] value = (byte[]) reader.get(db.DATA.DATA);
            Assert.assertArrayEquals(new byte[] { 1, 2, 3 }, value);
        }
    } finally {
        reader.close();
    }
    conn.close();
}

